const fractions={'½':.5,'¼':.25,'¾':.75,'⅓':1/3,'⅔':2/3};
const ingredientHeads=/^(ingredients?|sangkap|you'?ll need)\s*:?$/i;
const stepHeads=/^(instructions?|method|steps?|paraan|paano lutuin|procedure)\s*:?$/i;
const groupLine=/^[\p{L}][\p{L}\s&-]{1,35}:$/u;
const noise=[/^#/,/^@\S+$/,/^follow( for more)?$/i,/link in bio/i,/full recipe below/i,/^\d[\d,]* likes?$/i,/^view all \d+ comments?$/i,/^\d+[smhdw]$/i,/^add a comment/i];
const units='kg|kilo|g|gram(?:s)?|mg|ml|l|cup(?:s)?|tasa|tbsp|tablespoon(?:s)?|kutsara|tsp|teaspoon(?:s)?|kutsarita|oz|ounce(?:s)?|lb|pound(?:s)?|piece(?:s)?|piraso|clove(?:s)?|can(?:s)?|pack(?:s)?|dakot';
const aliases={baboy:'pork',manok:'chicken',isda:'fish',hipon:'shrimp',itlog:'egg',kanin:'rice',bigas:'rice',toyo:'soy',suka:'vinegar',patis:'fish sauce',bawang:'garlic',sibuyas:'onion',kamatis:'tomato',luya:'ginger',mantika:'oil',asin:'salt',paminta:'pepper',gata:'coconut milk',sitaw:'green beans',talong:'eggplant',monggo:'mung',tokwa:'tofu','ground beef':'beef','green onions':'onion','minced garlic':'garlic','sesame oil':'oil','soy sauce':'soy'};
function cleanLine(line){return line.replace(/[\u{1F300}-\u{1FAFF}\u2600-\u27BF]/gu,'').replace(/^[-*•]\s*/,'').replace(/\s+/g,' ').trim();}
export function cleanRecipeText(text){return text.split(/\r?\n/).map(cleanLine).filter(line=>line&&!noise.some(rule=>rule.test(line))).join('\n');}
function number(raw=''){const value=raw.trim();if(fractions[value]!==undefined)return fractions[value];const mixed=value.match(/^(\d+)\s+([½¼¾⅓⅔])$/);if(mixed)return Number(mixed[1])+fractions[mixed[2]];const slash=value.match(/^(\d+)\s*\/\s*(\d+)$/);if(slash)return Number(slash[1])/Number(slash[2]);return Number(value)||0;}
function grams(quantity,unit,item){const u=unit.toLowerCase(),name=item.toLowerCase();if(['g','gram','grams'].includes(u))return quantity;if(['kg','kilo'].includes(u))return quantity*1000;if(['ml'].includes(u))return /sesame oil/.test(name)?quantity*.92:/soy sauce|toyo/.test(name)?quantity*1.1:quantity;if(u==='l')return quantity*1000;if(['oz','ounce','ounces'].includes(u))return quantity*28.3495;if(['lb','pound','pounds'].includes(u))return quantity*453.592;if(['tbsp','tablespoon','tablespoons','kutsara'].includes(u))return quantity*(/oil|mantika/.test(name)?14:15);if(['tsp','teaspoon','teaspoons','kutsarita'].includes(u))return quantity*5;if(['clove','cloves'].includes(u))return quantity*3;if(['piece','pieces','piraso'].includes(u)&&/egg|itlog/.test(name))return quantity*50;if(['cup','cups','tasa'].includes(u)&&/rice|bigas|kanin/.test(name))return quantity*185;if(['cup','cups','tasa'].includes(u)&&/oat/.test(name))return quantity*80;return null;}
export function parseIngredientLine(line,servings=1){const original=line.trim(),perServing=/\/?\s*per\s*serving|\/serving|each|per person/i.test(original),note=original.match(/\(([^)]+)\)/)?.[1]||'',plain=original.replace(/\([^)]+\)/g,'').replace(/\/?\s*per\s*serving|\/serving|each|per person/ig,'').trim();const match=plain.match(new RegExp(`^((?:\\d+\\s+)?[½¼¾⅓⅔]|\\d+(?:\\.\\d+)?(?:\\s*\\/\\s*\\d+)?)?\\s*(${units})?\\s+(.+)$`,'i'));if(!match)return {read:original,item:plain,quantity:0,unit:'',grams:null,note,perServing,notCounted:true};const quantity=number(match[1]||''),unit=match[2]||'',item=match[3].replace(/\s+to taste$/i,'').trim(),total=perServing?quantity*servings:quantity,value=quantity&&unit?grams(total,unit,item):null;return {read:original,item,quantity:total,unit,grams:value,note,perServing,notCounted:value===null};}
function strength(line){return line.replace(/[*_#]/g,'').trim();}
export function matchIngredient(name,ingredientMap){const raw=name.toLowerCase().replace(/[^a-z\s]/g,' ').replace(/\b(extra lean|large|small|raw weight|raw|boneless|fillet|fillets|minced|fresh|of choice)\b/g,'').replace(/\s+/g,' ').trim(),translated=Object.entries(aliases).find(([word])=>raw.includes(word))?.[1]||raw,entries=Object.entries(ingredientMap),direct=entries.find(([id,item])=>translated.includes(id)||item.name.toLowerCase().includes(translated)||translated.includes(item.name.toLowerCase().split(',')[0]));if(direct)return direct[0];let best='',score=0;for(const [id,item]of entries){const words=new Set((id+' '+item.name).toLowerCase().split(/[^a-z]+/).filter(x=>x.length>2)),hits=translated.split(' ').filter(word=>words.has(word)).length;if(hits>score){score=hits;best=id;}}return score?best:'';}
export function parseRecipeText(raw,ingredientMap){const text=cleanRecipeText(raw),lines=text.split('\n'),recipeLine=lines.find(line=>/^recipe\s*:/i.test(line)),title=strength(recipeLine?.replace(/^recipe\s*:/i,'')||lines.find(line=>!ingredientHeads.test(line)&&!stepHeads.test(line)&&!/^\(?per serving/i.test(line)&&!/^\d/.test(line))||'New recipe'),servingText=lines.find(line=>/(serves?|makes?|per serving|good for|para sa).{0,18}\d/i.test(line))||'',servingMatch=servingText.match(/per serving\s*-\s*(\d+)\s*total/i)||servingText.match(/(?:serves?|makes?|total|good for|para sa)[^\d]*(\d+)/i),servings=Number(servingMatch?.[1]||4),creatorCalories=Number(lines.find(line=>/^\d+\s*calories?/i.test(line))?.match(/\d+/)?.[0]||0),macroLine=lines.find(line=>/\d+gP\s*\|/i.test(line))||'',macroValues=[...macroLine.matchAll(/(\d+)g([PCF])/ig)].reduce((out,m)=>(out[m[2].toUpperCase()]=Number(m[1]),out),{}),creatorNutrition=creatorCalories?{kcal:creatorCalories,protein:macroValues.P||0,carbs:macroValues.C||0,fat:macroValues.F||0}:null,timeLine=lines.find(line=>/(prep|cook|total time|\d+\s*(mins?|minutes?|hours?))/i.test(line))||'',timeMatch=timeLine.match(/(\d+)\s*(hours?|mins?|minutes?)/i),time=timeMatch?Number(timeMatch[1])*(timeMatch[2].toLowerCase().startsWith('hour')?60:1):30;let mode='',group='Ingredients',rows=[],steps=[];for(const line of lines){if(ingredientHeads.test(line)){mode='ingredients';continue;}if(stepHeads.test(line)){mode='steps';continue;}if(line===title||line===servingText||line===timeLine||/^\d+\s*calories?/i.test(line)||line===macroLine)continue;if(mode==='ingredients'&&groupLine.test(line)){group=line.slice(0,-1);continue;}const numbered=line.match(/^\d+[.)]\s*(.+)$/);if(mode==='steps'||numbered&&/[.!]$/.test(numbered[1])){mode='steps';steps.push((numbered?.[1]||line).trim());continue;}if(mode==='ingredients'||/^(?:\d|[½¼¾⅓⅔])/.test(line)){mode='ingredients';const row=parseIngredientLine(line,servings);row.group=group;row.basis=/topping/i.test(group)&&/rice|pasta|oat|lentil|noodle/i.test(row.item)?'cooked':'dry';row.match=matchIngredient(row.item,ingredientMap);if(row.match&&row.grams!==null)row.notCounted=false;rows.push(row);}}
 const stepItems=steps.flatMap(step=>Object.keys(aliases).filter(word=>step.toLowerCase().includes(word))).map(word=>aliases[word]);for(const name of new Set(stepItems))if(!rows.some(row=>(row.match||row.item.toLowerCase()).includes(name)))rows.push({read:name,item:name,quantity:0,unit:'',grams:null,note:'Mentioned in method',group:'Ingredients',match:matchIngredient(name,ingredientMap),notCounted:true});
 return {source:'Pasted recipe',name:title,servings,time,mealType:/egg|oat|breakfast/i.test(rows.map(row=>row.item).join(' '))?'breakfast':'dinner',rows,steps,creatorNutrition,text};}

async function imageForOcr(file){const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(bitmap,0,0);const sample=context.getImageData(0,0,canvas.width,canvas.height),pixels=sample.data;let light=0;for(let i=0;i<pixels.length;i+=40)light+=(pixels[i]+pixels[i+1]+pixels[i+2])/3;const dark=light/(pixels.length/40)<105;if(dark){for(let i=0;i<pixels.length;i+=4){pixels[i]=255-pixels[i];pixels[i+1]=255-pixels[i+1];pixels[i+2]=255-pixels[i+2];}context.putImageData(sample,0,0);}return canvas;}
export async function recognizePhotos(files,onProgress=()=>{}){const tesseract=(await import('./vendor/tesseract/tesseract.esm.min.js')).default,worker=await tesseract.createWorker('eng',1,{workerPath:'/vendor/tesseract/worker.min.js',corePath:'/vendor/tesseract/tesseract-core-simd-lstm.wasm.js',langPath:'/vendor/tessdata',logger:message=>{if(message.status==='recognizing text')onProgress(Math.round((message.progress||0)*100));}}),parts=[];try{for(const file of files){const image=await imageForOcr(file),read=await worker.recognize(image);parts.push(cleanRecipeText(read.data.text));}}finally{await worker.terminate();}return parts.join('\n');}
